{"id":1153576,"title":"Street Fighter","original_title":"Street Fighter","tagline":"Ready. Set. Fight.","overview":"In 1993, estranged Street Fighters Ryu and Ken Masters are thrown back into combat when the mysterious Chun-Li recruits them for the next World Warrior Tournament: a brutal clash of fists, fate, and fury. But behind this battle royale lies a deadly conspiracy that forces them to face off against each other and the demons of their past. And if they don't, it's GAME OVER!","release_date":"2026-10-13","runtime":120,"original_language":"en","poster_url":"https://image.tmdb.org/t/p/w500/dJPT2Uf12X6aFg8i5N67NTpIZ9t.jpg","backdrop_url":"https://image.tmdb.org/t/p/w1280/3BBjkQmdGacKYZtpmK2vIfuDmON.jpg","trailer_youtube_key":"U6sbm1OaJb8","vote_average":6.3,"vote_count":226,"popularity":58.182,"status":"Released"},
{"id":1644210,"title":"Robotica","original_title":"Robotica","tagline":"Built for pleasure. Out For Blood.","overview":"Two security guards working the midnight shift in an adult toy company find themselves the target of a half-dismantled and severely malfunctioning female sex doll prototype named Robotica.","release_date":"2026-08-01","runtime":71,"original_language":"en","poster_url":"https://image.tmdb.org/t/p/w500/fZD9b4RRmFWwYVn6MCcrHebTDDc.jpg","backdrop_url":"https://image.tmdb.org/t/p/w1280/g6yVfiCdVITgpMRY1R9VHRxR4uu.jpg","trailer_youtube_key":"_n9T5dpQsAU","vote_average":2.5,"vote_count":4,"popularity":57.933,"status":"Released"},
{"id":1108427,"title":"Moana","original_title":"Moana","tagline":"The ocean chose her for a reason.","overview":"Teenage Moana answers the Ocean's call and, for the first time, voyages beyond the reef of her island of Motunui with infamous demigod Maui on an unforgettable journey to restore prosperity to her people.","release_date":"2026-07-08","runtime":115,"original_language":"en","poster_url":"https://image.tmdb.org/t/p/w500/gaet1xQ2nxrG0V1Ep9T20ZMNEIC.jpg","backdrop_url":"https://image.tmdb.org/t/p/w1280/c6BPbkO5Npt1OdwttAxCFo06wtH.jpg","trailer_youtube_key":"EEz5xbzYPKI","vote_average":7.4,"vote_count":1045,"popularity":56.798,"status":"Released"},
{"id":1377237,"title":"Runner","original_title":"Runner","tagline":"Next-day delivery isn't an option.","overview":"A former soldier is thrown into a brutal race against time when a critical medical delivery makes him and his unlikely partner the targets of a ruthless cartel. As the mission spirals into a deadly manhunt, every detour, delay, and bullet pushes them closer to failure. With betrayal closing in from every side, they must survive the chase and deliver their cargo to save the life of a little girl.","release_date":"2026-09-07","runtime":98,"original_language":"en","poster_url":"https://image.tmdb.org/t/p/w500/vJk2TW1QZAmBiD7oj9ZF9EPTYY1.jpg","backdrop_url":"https://image.tmdb.org/t/p/w1280/npXZNWjOEYrqdMDPQ11SGBrXqAG.jpg","trailer_youtube_key":"B6Z9MM1LhEA","vote_average":8.2,"vote_count":830,"popularity":56.35,"status":"Released"},
{"id":1437396,"title":"Your Mother Your Mother Your Mother","original_title":"Your Mother Your Mother Your Mother","tagline":"To be a parent is to be at war.","overview":"Latif, a devoutly religious hitman, struggles to balance work, faith and fatherhood. When his wife dies, he embarks on a desperate journey across Houston to protect his children, confronting the forces closing in around him – and the beliefs threatening to unravel within.","release_date":"2026-09-25","runtime":112,"original_language":"en","poster_url":"https://image.tmdb.org/t/p/w500/4KaPZSKnInnArErTTgy9Oy14leR.jpg","backdrop_url":"https://image.tmdb.org/t/p/w1280/45Mbs6dmn2W0hvuyxXPDkKREHpP.jpg","trailer_youtube_key":"uEcoV-ngH38","vote_average":6.7,"vote_count":58,"popularity":55.217,"status":"Released"},
{"id":1766192,"title":"Insidious Rewind","original_title":"Insidious Rewind","tagline":"Once You Press Play, You Can't Go Back","overview":"Searching for her missing brother, a young woman traces his final signal to an abandoned warehouse, where she discovers a collection of cursed VHS tapes. Captured and forced to watch, she endures four found-footage nightmares that may reveal what happened to him—and what now awaits her.","release_date":null,"runtime":79,"original_language":"en","poster_url":"https://image.tmdb.org/t/p/w500/AeeAAx83NSPSqBO66hjbQrZGvFb.jpg","backdrop_url":"https://image.tmdb.org/t/p/w1280/n3McMv40zcn4rZyUHrL3UVKGWQa.jpg","trailer_youtube_key":"2fCJuqrc13w","vote_average":0.0,"vote_count":0,"popularity":55.186,"status":"Released"},
{"id":1567605,"title":"Ebenezer","original_title":"Ebenezer","tagline":"Before he was Scrooge, he was…","overview":"An elderly miser embarks on a supernatural journey after visits from the ghost of his former business partner and the Spirits of Christmas Past, Present, and Yet to Come force him to confront his past and fight for a second chance at happiness.","release_date":"2026-11-11","runtime":115,"original_language":"en","poster_url":"https://image.tmdb.org/t/p/w500/wbTHJ5VzOjEq02PYHkLAL7yhhBn.jpg","backdrop_url":"https://image.tmdb.org/t/p/w1280/oveb9ughaDh4GkjmVHvSgFnEzlM.jpg","trailer_youtube_key":"l_Ozo1xUgbU","vote_average":8.0,"vote_count":9,"popularity":55.154,"status":"Released"},
{"id":1697911,"title":"Drummer Boy","original_title":"Drummer Boy","tagline":"Forgiveness is revolutionary.","overview":"As America’s fight for independence begins, a young drummer boy, an enslaved woman, and a divided family search for freedom. Through battle and loss, music carries hope in a deeply human story of faith and forgiveness.","release_date":"2026-11-05","runtime":129,"original_language":"en","poster_url":"https://image.tmdb.org/t/p/w500/bhjdgMm2fFrysSzVqv5RwRwIbVf.jpg","backdrop_url":"https://image.tmdb.org/t/p/w1280/5KF459N6jOfRV7kV9XV7ZQdCLKK.jpg","trailer_youtube_key":"rXaR4nXRvOY","vote_average":7.8,"vote_count":5,"popularity":54.749,"status":"Released"}
]$seed$::jsonb) as m(
  id integer, title text, original_title text, tagline text, overview text,
